-- bastion v2: visitors and the durable dossier (spec 21 §6.3).
--
-- Generated by `drizzle-kit generate`, then hand-edited so that every statement is additive
-- and idempotent:
--
--   * Additive: v1 keeps working against the migrated database (a preview build of v2 runs this
--     against the shared production branch before v2 is promoted). Nothing is dropped or
--     renamed; `sessions`, `magic_links` and `events.actor_id` stay for history.
--   * Idempotent (IF NOT EXISTS, inline constraints): a database built by `drizzle-kit push`
--     of the v2 schema already has these objects; scripts/migrate.mjs baselines such databases
--     and this file must then apply as a no-op.
--
-- The first statement takes an ACCESS EXCLUSIVE lock on `events`, which serialises two builds
-- migrating at once: the second waits, then finds every object present (and records 0002 a
-- second time, which is harmless: drizzle reads only the latest journal entry).

ALTER TABLE "events" ADD COLUMN IF NOT EXISTS "actor" text;
--> statement-breakpoint
ALTER TABLE "dossiers" ALTER COLUMN "user_id" DROP NOT NULL;
--> statement-breakpoint
ALTER TABLE "dossiers" ADD COLUMN IF NOT EXISTS "visitor" text;
--> statement-breakpoint
ALTER TABLE "dossiers" ADD COLUMN IF NOT EXISTS "error" text;
--> statement-breakpoint
ALTER TABLE "evidence_items" ALTER COLUMN "url" SET DEFAULT '';
--> statement-breakpoint
ALTER TABLE "evidence_items" ALTER COLUMN "title" SET DEFAULT '';
--> statement-breakpoint
ALTER TABLE "evidence_items" ADD COLUMN IF NOT EXISTS "kind" text;
--> statement-breakpoint
ALTER TABLE "evidence_items" ADD COLUMN IF NOT EXISTS "product" text;
--> statement-breakpoint
ALTER TABLE "evidence_items" ADD COLUMN IF NOT EXISTS "locator" jsonb;
--> statement-breakpoint
ALTER TABLE "evidence_items" ADD COLUMN IF NOT EXISTS "excerpt" text;
--> statement-breakpoint
ALTER TABLE "evidence_items" ADD COLUMN IF NOT EXISTS "inkprint_hash" text;
