CREATE TABLE IF NOT EXISTS "dossier_steps" (
	"dossier_id" uuid NOT NULL,
	"stage" text NOT NULL,
	"status" text NOT NULL,
	"attempt" integer DEFAULT 0 NOT NULL,
	"lease_until" timestamp with time zone DEFAULT 'epoch' NOT NULL,
	"not_before" timestamp with time zone DEFAULT now() NOT NULL,
	"started_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	"output" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"error" text,
	CONSTRAINT "dossier_steps_dossier_id_stage_pk" PRIMARY KEY("dossier_id","stage"),
	CONSTRAINT "dossier_steps_dossier_id_dossiers_id_fk" FOREIGN KEY ("dossier_id") REFERENCES "public"."dossiers"("id") ON DELETE cascade ON UPDATE no action
);
