	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "receipts_dossier_id_dossiers_id_fk" FOREIGN KEY ("dossier_id") REFERENCES "public"."dossiers"("id") ON DELETE cascade ON UPDATE no action
);
--> statement-breakpoint
-- Re-assert the append-only guard from 0001 (DR-0019). A database built by `drizzle-kit push`
-- never ran 0001 — push knows only the table definitions — yet scripts/migrate.mjs baselines it
-- as applied. Re-installing the guard here makes every migrated database append-only, whatever
-- built it. Same function body and trigger names as 0001, so on a database that has them this
-- replaces them with identical copies inside the migration's transaction.
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE "events" FROM PUBLIC;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION "events_reject_mutation"() RETURNS trigger
	LANGUAGE plpgsql
	AS $$
BEGIN
	RAISE EXCEPTION 'events is append-only: % is not permitted', TG_OP
		USING ERRCODE = 'insufficient_privilege';
END;
$$;
--> statement-breakpoint
DROP TRIGGER IF EXISTS "events_no_update" ON "events";
--> statement-breakpoint
CREATE TRIGGER "events_no_update"
	BEFORE UPDATE ON "events"
	FOR EACH ROW EXECUTE FUNCTION "events_reject_mutation"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "events_no_delete" ON "events";
--> statement-breakpoint
CREATE TRIGGER "events_no_delete"
	BEFORE DELETE ON "events"
	FOR EACH ROW EXECUTE FUNCTION "events_reject_mutation"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "events_no_truncate" ON "events";
--> statement-breakpoint
CREATE TRIGGER "events_no_truncate"
	BEFORE TRUNCATE ON "events"
	FOR EACH STATEMENT EXECUTE FUNCTION "events_reject_mutation"();
